details.command:
PODS=$(kubectl -n default get pods -l app=app -o jsonpath='{range .items[*]}{.metadata.name} {.status.podIP}{"
"}{end}'); echo "$PODS"; for p in $PODS; do set -- $p; echo "--- $1 ($2)"; kubectl -n default exec "$1" -- curl -sS -m 5 -o /dev/null -w 'local http_code=%{http_code}
' http://127.0.0.1:80/; done; echo ---; A=$(echo "$PODS" | awk 'NR==1{print $1}'); B_IP=$(echo "$PODS" | awk 'NR==2{print $2}'); kubectl -n default exec "$A" -- curl -sS -m 5 -o /dev/null -w "cross-pod http_code=%{http_code}
" "http://$B_IP:80/"
